/**
 * Reload model-family-specific runtime resources when crossing provider families.
 *
 * Why this exists:
 * - Provider-specific packages/extensions can change active tools and resource output.
 * - Pi saves the newly selected model before emitting `model_select`, but package
 *   membership is only re-resolved by a full runtime reload.
 * - Same-family model switches already get lightweight `model_select` sync and
 *   resource refresh; reloading there would just burn cache and time.
 */

import type { ExtensionAPI } from "@valkyriweb/pi-coding-agent";
import { providerFamily, shouldReloadForProviderFamilySwitch } from "./model-family.ts";

const STATUS_KEY = "provider-family-reload";

export default function providerFamilyReload(pi: ExtensionAPI): void {
	let reloadQueued = false;

	pi.on("model_select", async (event, ctx) => {
		if (!shouldReloadForProviderFamilySwitch(event.previousModel, event.model)) return;
		if (reloadQueued) return;

		reloadQueued = true;
		const previous = providerFamily(event.previousModel);
		const next = providerFamily(event.model);
		if (ctx.hasUI) ctx.ui.setStatus(STATUS_KEY, `Reloading provider-family resources: ${previous} → ${next}`);

		await ctx.reload();
	});

	pi.on("session_start", async (_event, ctx) => {
		reloadQueued = false;
		if (ctx.hasUI) ctx.ui.setStatus(STATUS_KEY, undefined);
	});

	pi.on("session_shutdown", async () => {
		reloadQueued = false;
	});
}

