import type { Model } from "@valkyriweb/pi-ai";

export type ReloadProviderFamily = "claude-bridge" | "openai-codex" | "other";

export function providerFamily(model: Model<any> | undefined): ReloadProviderFamily {
	if (!model) return "other";
	if (model.provider === "claude-bridge") return "claude-bridge";
	if (model.provider === "openai-codex") return "openai-codex";
	return "other";
}

export function shouldReloadForProviderFamilySwitch(
	previousModel: Model<any> | undefined,
	nextModel: Model<any> | undefined,
): boolean {
	const previous = providerFamily(previousModel);
	const next = providerFamily(nextModel);
	if (previous === "other" || next === "other") return false;
	return previous !== next;
}

