test("the reload fires after the model_select emit loop, not inline", async () => {
	const handlers = new Map();
	providerFamilyReload(recordingPi(handlers));
	const modelSelect = handlers.get("model_select");

	let reloads = 0;
	const ctx = {
		hasUI: false,
		async reload() {
			reloads += 1;
		},
	};

	// The handler must return before the reload runs, so a sibling subscriber emitted
	// after it would still observe the live (not-yet-reloaded) ctx.
	await modelSelect({ previousModel: model("openai-codex"), model: model("claude-bridge") }, ctx);
