test("session_start reopens the reload guard and clears the status indicator", async () => {
	const handlers = new Map();
	providerFamilyReload(recordingPi(handlers));
	const modelSelect = handlers.get("model_select");
	const sessionStart = handlers.get("session_start");

	const statusCalls = [];
	let reloads = 0;
	const ctx = {
		hasUI: true,
		ui: {
			setStatus(key, value) {
				statusCalls.push({ key, value });
			},
		},
		async reload() {
			reloads += 1;
		},
	};

	await modelSelect({ previousModel: model("openai-codex"), model: model("claude-bridge") }, ctx);
	await flush();
	assert.equal(reloads, 1);

	// Guard still latched: a second switch is suppressed until something resets it.
	await modelSelect({ previousModel: model("claude-bridge"), model: model("openai-codex") }, ctx);
	await flush();
	assert.equal(reloads, 1);

	await sessionStart({}, ctx);
	assert.deepEqual(statusCalls.at(-1), { key: "provider-family-reload", value: undefined });

	// Guard reopened: a later switch reloads again.
	await modelSelect({ previousModel: model("claude-bridge"), model: model("openai-codex") }, ctx);
	await flush();
	assert.equal(reloads, 2);
});

