	await flush();
	assert.equal(reloads, 1);

	await sessionShutdown({}, ctx);

	await modelSelect({ previousModel: model("claude-bridge"), model: model("openai-codex") }, ctx);
	await flush();
	assert.equal(reloads, 2);
});

test("a failed reload reopens the guard so the next switch retries", async () => {
	const handlers = new Map();
	providerFamilyReload(recordingPi(handlers));
	const modelSelect = handlers.get("model_select");

	const statusCalls = [];
	let attempts = 0;
	const ctx = {
		hasUI: true,
		ui: {
			setStatus(key, value) {
				statusCalls.push({ key, value });
			},
		},
		async reload() {
			attempts += 1;
			if (attempts === 1) throw new Error("reload boom");
		},
	};

	await modelSelect({ previousModel: model("openai-codex"), model: model("claude-bridge") }, ctx);
	await flush();
	assert.equal(attempts, 1);
	assert.deepEqual(statusCalls.at(-1), { key: "provider-family-reload", value: undefined }, "failed reload clears the status");

	await modelSelect({ previousModel: model("claude-bridge"), model: model("openai-codex") }, ctx);
	await flush();
	assert.equal(attempts, 2, "guard reopened so the next switch retries the reload");
});

