	await modelSelect({ previousModel: model("claude-bridge"), model: model("openai-codex") }, ctx);
	await flush();
	assert.equal(reloads, 1);

	await sessionStart({}, ctx);
	assert.deepEqual(statusCalls.at(-1), { key: "provider-family-reload", value: undefined });

	// Guard reopened: a later switch reloads again.
	await modelSelect({ previousModel: model("claude-bridge"), model: model("openai-codex") }, ctx);
	await flush();
	assert.equal(reloads, 2);
});

