import assert from "node:assert/strict";
import { test } from "node:test";

import providerFamilyReload from "./src/index.ts";
import {
	providerFamily,
	shouldReloadForProviderFamilySwitch,
} from "./src/model-family.ts";

const model = (provider, id = "model") => ({ provider, id });

// The reload is deferred to a later event-loop tick (see src/index.ts), so tests
// drain two `setImmediate` turns to let the scheduled reload — and its catch
// handler — settle before asserting.
const flush = async () => {
	await new Promise((resolve) => setImmediate(resolve));
	await new Promise((resolve) => setImmediate(resolve));
};

const recordingPi = (handlers) => ({
	registerCommand() {
		throw new Error("provider-family reload must not register a slash command");
	},
	on(event, handler) {
		handlers.set(event, handler);
	},
});

test("providerFamily classifies reload-relevant providers", () => {
	assert.equal(providerFamily(model("claude-bridge")), "claude-bridge");
	assert.equal(providerFamily(model("openai-codex")), "openai-codex");
	assert.equal(providerFamily(model("openai")), "other");
	assert.equal(providerFamily(undefined), "other");
});

test("shouldReloadForProviderFamilySwitch only trips across claude/codex boundary", () => {
	assert.equal(shouldReloadForProviderFamilySwitch(model("openai-codex", "a"), model("openai-codex", "b")), false);
	assert.equal(shouldReloadForProviderFamilySwitch(model("claude-bridge", "a"), model("claude-bridge", "b")), false);
	assert.equal(shouldReloadForProviderFamilySwitch(model("openai-codex"), model("claude-bridge")), true);
	assert.equal(shouldReloadForProviderFamilySwitch(model("claude-bridge"), model("openai-codex")), true);
	assert.equal(shouldReloadForProviderFamilySwitch(model("openai"), model("openai-codex")), false);
	assert.equal(shouldReloadForProviderFamilySwitch(undefined, model("openai-codex")), false);
});

test("extension reloads directly on provider-family switch without queuing user text", async () => {
	const handlers = new Map();
	const sentUserMessages = [];
	const pi = {
		registerCommand() {
			throw new Error("provider-family reload must not register a slash command");
		},
		on(event, handler) {
			handlers.set(event, handler);
		},
		sendUserMessage(content, options) {
			sentUserMessages.push({ content, options });
		},
	};

	providerFamilyReload(pi);

	const modelSelect = handlers.get("model_select");
	let reloads = 0;
	const ctx = {
		hasUI: false,
		async reload() {
			reloads += 1;
		},
	};

	await modelSelect({ previousModel: model("openai-codex", "a"), model: model("openai-codex", "b") }, ctx);
	assert.equal(reloads, 0);
	assert.equal(sentUserMessages.length, 0);

	await modelSelect({ previousModel: model("openai-codex"), model: model("claude-bridge") }, ctx);
	assert.equal(reloads, 1);
	assert.equal(sentUserMessages.length, 0);

	await modelSelect({ previousModel: model("claude-bridge"), model: model("openai-codex") }, ctx);
	assert.equal(reloads, 1, "in-flight reload suppresses duplicates until the reloaded extension instance takes over");
});

